#include <linux/security.h>
#include <linux/task_io_accounting.h>

int get_task_io_priority(struct task_struct *p) {
    int ret;

    /* Check security context for permission to get I/O priority */
    ret = security_task_get_io_priority(p);
    if (ret)
        return ret;

    /* Initialize to default priority if no I/O context exists */
    if (!p->io_context)
        return 0;

    /* Retrieve the I/O priority from the task's I/O context */
    return p->io_context->ioprio;
}
